package commands

// Default-output goldens for every command that renders timestamps.
//
// The expectations in testdata/timeoutput/ were generated by running THIS
// file against the code of main (1396c68), before --time-output existed,
// with ARCLI_UPDATE_TIME_GOLDEN=1. The file therefore uses nothing but
// NewRoot, execCmd, writeTestConfig, fastPolls and the standard library, so
// it still compiles against main and can regenerate them there. Do not
// regenerate the goldens from a branch that changes timestamp rendering:
// they pin the legacy (no flag) output byte for byte.

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
)

// Server fixture timestamps. String-typed fields carry fractional seconds
// with a non-UTC offset, a zero value, an unparseable value and null;
// time.Time-typed fields carry fractional seconds with an offset.
const (
	tsFrac         = "2026-09-07T16:00:00.123456789-03:00"
	tsHalf         = "2026-09-07T19:05:00.5Z"
	tsZero         = "0001-01-01T00:00:00Z"
	tsBad          = "not-a-time"
	tsTimeVal      = "2026-09-07T16:00:01.987654321-03:00"
	tsTimeVal2     = "2026-09-08T01:02:03.000001+02:00"
	goldenBackupID = "backup-20260907-190000-abcdef12"
)

var goldenPolicy1 = `{"id":1,"name":"p-frac","database":"metrics","measurement":"cpu","retention_days":30,"buffer_days":1,"is_active":true,"last_execution_time":"` + tsFrac + `","last_execution_status":"completed","last_deleted_count":42,"created_at":"` + tsHalf + `","updated_at":"` + tsFrac + `"}`
var goldenPolicy2 = `{"id":2,"name":"p-odd","database":"metrics","measurement":null,"retention_days":7,"buffer_days":0,"is_active":false,"last_execution_time":"` + tsZero + `","last_execution_status":null,"last_deleted_count":null,"created_at":"` + tsBad + `","updated_at":""}`
var goldenPolicy3 = `{"id":3,"name":"p-null","database":"metrics","measurement":null,"retention_days":7,"buffer_days":0,"is_active":true,"last_execution_time":null,"last_execution_status":null,"last_deleted_count":null,"created_at":"` + tsZero + `","updated_at":"` + tsHalf + `"}`

var goldenCQ1 = `{"id":1,"name":"cq-frac","description":"d","database":"metrics","source_measurement":"cpu","destination_measurement":"cpu_1m","query":"SELECT 1 FROM metrics.cpu WHERE time >= {start_time} AND time < {end_time}","interval":"1m","tag_columns":["host"],"retention_days":null,"delete_source_after_days":null,"is_active":true,"last_execution_time":"` + tsFrac + `","last_execution_status":"completed","last_processed_time":"2026-09-07T19:00:00.75Z","last_records_written":5,"created_at":"` + tsHalf + `","updated_at":"` + tsFrac + `"}`
var goldenCQ2 = `{"id":2,"name":"cq-odd","description":null,"database":"metrics","source_measurement":"mem","destination_measurement":"mem_1m","query":"SELECT 1 FROM metrics.mem WHERE time >= {start_time} AND time < {end_time}","interval":"5m","tag_columns":null,"retention_days":null,"delete_source_after_days":null,"is_active":false,"last_execution_time":"` + tsBad + `","last_execution_status":null,"last_processed_time":null,"last_records_written":null,"created_at":"` + tsZero + `","updated_at":""}`

var goldenNode1 = `{"id":"n1","name":"node-1","role":"writer","state":"healthy","address":"10.0.0.1:9000","api_address":"10.0.0.1:8000","cluster_name":"c1","version":"26.09.3","started_at":"` + tsTimeVal + `","joined_at":"` + tsTimeVal2 + `","last_heartbeat":"` + tsTimeVal + `","failed_checks":0,"stats":{"cpu_usage":1.5,"memory_usage":2.5,"ingest_rate":10,"query_rate":2,"storage_used":2048,"connections":3,"active_queries":1,"compaction_jobs":0}}`
var goldenNode2 = `{"id":"n2","name":"node-2","role":"reader","state":"unknown","address":"10.0.0.2:9000","api_address":"10.0.0.2:8000","version":"26.09.3","started_at":"` + tsZero + `","joined_at":"` + tsZero + `","last_heartbeat":"` + tsZero + `","failed_checks":3,"stats":{}}`

var goldenToken1 = `{"id":1,"name":"admin","description":"root token","permissions":["read","write","delete","admin"],"created_at":"` + tsTimeVal + `","last_used_at":"` + tsTimeVal2 + `","enabled":true,"expires_at":"2027-01-01T03:00:00.123-03:00"}`
var goldenToken2 = `{"id":2,"name":"ro","permissions":["read"],"created_at":"` + tsTimeVal2 + `","enabled":false,"expires_at":null}`

var goldenManifest = `{"version":"1","backup_id":"` + goldenBackupID + `","created_at":"` + tsTimeVal + `","backup_type":"full","databases":[{"name":"metrics","measurements":[{"name":"cpu","file_count":2,"size_bytes":2048}],"file_count":2,"size_bytes":2048}],"total_files":2,"total_size_bytes":2048,"has_metadata":false,"has_config":false}`

func goldenProgress(op, status string) string {
	return `{"operation":"` + op + `","backup_id":"` + goldenBackupID + `","status":"` + status + `","total_files":2,"processed_files":1,"skipped_files":0,"total_bytes":2048,"processed_bytes":1024,"started_at":"` + tsTimeVal + `","completed_at":"` + tsTimeVal2 + `","error":"disk full"}`
}

