// runGoldenCase runs one case against a fresh fixture server and returns
// its stdout/stderr/error rendering with the random endpoint normalised.
func runGoldenCase(t *testing.T, tc goldenCase, extraArgs ...string) (string, *goldenServer) {
	t.Helper()
	fastPolls(t)
	g := newGoldenServer(t, tc.overrides)
	writeTestConfig(t, g.srv.URL, "tok")
	root := NewRoot(BuildInfo{Version: "test"})
	if tc.stdin != "" {
		root.SetIn(strings.NewReader(tc.stdin))
	}
	args := append(append([]string{}, tc.args...), extraArgs...)
	out, errOut, err := execCmd(t, root, args...)
	errText := "<nil>"
	if err != nil {
		errText = err.Error()
	}
	rendered := "--- stdout\n" + out + "--- stderr\n" + errOut + "--- err\n" + errText + "\n"
	return strings.ReplaceAll(rendered, g.srv.URL, "ENDPOINT"), g
}

func TestTimeOutputDefaultGolden(t *testing.T) {
	update := os.Getenv("ARCLI_UPDATE_TIME_GOLDEN") == "1"
	for _, tc := range timeOutputGoldenCases() {
		t.Run(tc.name, func(t *testing.T) {
			got, _ := runGoldenCase(t, tc)
			path := filepath.Join("testdata", "timeoutput", tc.name+".golden")
			if update {
				if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, []byte(got), 0o644); err != nil {
					t.Fatal(err)
				}
				return
			}
			want, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if got != string(want) {
				t.Errorf("default output differs from main\n--- want\n%s\n--- got\n%s", want, got)
			}
		})
	}
}
